import pandas as pd
import numpy as np

def clean(df):
    df = df.copy()
    # Fix Region label variants and typos
    region_map = {
        'north': 'North', 'Nort': 'North',
        'east': 'East',
        'Suoth': 'South',
        'Wst': 'West'
    }
    df['Region'] = df['Region'].apply(
        lambda x: region_map.get(x, x) if isinstance(x, str) else x
    )
    # Parse Price (handles '$6.00' style text numbers)
    df['Price'] = df['Price'].apply(
        lambda x: float(str(x).replace('$', '').replace(',', '').strip())
        if pd.notna(x) else np.nan
    )
    # Fix invalid dates like '2026-14-01' (month/day swapped) -> set NaT safely
    def parse_date(v):
        if pd.isna(v):
            return pd.NaT
        d = pd.to_datetime(v, errors='coerce', format='%Y-%m-%d')
        if pd.isna(d):
            # try swapping month/day for entries like 2026-14-01
            parts = str(v).split('-')
            if len(parts) == 3:
                try:
                    y, m, dd = int(parts[0]), int(parts[1]), int(parts[2])
                    if m > 12 and dd <= 12:
                        return pd.Timestamp(year=y, month=dd, day=min(m, 28))
                except Exception:
                    pass
            return pd.NaT
        return d
    df['Date'] = df['Date'].apply(parse_date)
    # Ensure Quantity numeric
    df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    return df

def answer(df):
    df = clean(df)
    out = {}
    for region, grp in df.groupby('Region'):
        if pd.isna(region):
            continue
        out[str(region)] = float(grp['Quantity'].sum())
    return out
